#include <stdio.h>
#include <string.h>

/**
 * reverse_string_inplace - Reverses a null-terminated string in place.
 *
 * @str: A pointer to the null-terminated string to be reversed.
 *
 * Return: A pointer to the now reversed string (or NULL if an error occurred,
 *          though this implementation doesn't return anything on failure).
 */
void reverse_string_inplace(char *str) {
    if (str == NULL) {
        // Handle the case where the input pointer is NULL
        return;
    }

    // 1. Initialize pointers for the start, end, and a temporary character
    int start = 0;
    int end = strlen(str) - 1;
    char temp;

    // 2. Loop until the start pointer crosses or meets the end pointer
    while (start < end) {
        // a. Store the character at the start position
        temp = str[start];

        // b. Replace the character at the start position with the character from the end
        str[start] = str[end];

        // c. Replace the character at the end position with the stored character
        str[end] = temp;

        // Move the pointers inward
        start++;
        end--;
    }
}

// --- Example Usage ---
