    // Test Case 1: Standard string
    char s1[] = "hello world";
    printf("Original string 1: \"%s\"\n", s1);
    reverse_string_inplace(s1);
    printf("Reversed string 1: \"%s\"\n\n", s1); // Expected: dlrow olleh

    // Test Case 2: Palindrome (should remain the same)
    char s2[] = "madam";
    printf("Original string 2: \"%s\"\n", s2);
    reverse_string_inplace(s2);
    printf("Reversed string 2: \"%s\"\n\n", s2); // Expected: madam

